    SET(WdfFdoInitOpenRegistryKey, PFN_WDFFDOINITOPENREGISTRYKEY, HmWdfFdoInitOpenRegistryKey);
    SET(WdfDeviceCreate, PFN_WDFDEVICECREATE, HmWdfDeviceCreate);
    SET(WdfObjectGetTypedContextWorker, PFN_WDFOBJECTGETTYPEDCONTEXTWORKER, HmWdfObjectGetTypedContextWorker);
    SET(WdfDeviceAssignProperty, PFN_WDFDEVICEASSIGNPROPERTY, HmWdfDeviceAssignProperty);
    SET(WdfDeviceCreateDeviceInterface, PFN_WDFDEVICECREATEDEVICEINTERFACE, HmWdfDeviceCreateDeviceInterface);
    SET(WdfDeviceOpenRegistryKey, PFN_WDFDEVICEOPENREGISTRYKEY, HmWdfDeviceOpenRegistryKey);
    SET(WdfRegistryQueryULong, PFN_WDFREGISTRYQUERYULONG, HmWdfRegistryQueryULong);
    SET(WdfRegistryAssignULong, PFN_WDFREGISTRYASSIGNULONG, HmWdfRegistryAssignULong);
    SET(WdfRegistryAssignUnicodeString, PFN_WDFREGISTRYASSIGNUNICODESTRING, HmWdfRegistryAssignUnicodeString);
    SET(WdfRegistryRemoveValue, PFN_WDFREGISTRYREMOVEVALUE, HmWdfRegistryRemoveValue);
    SET(WdfRegistryClose, PFN_WDFREGISTRYCLOSE, HmWdfRegistryClose);
    SET(WdfIoQueueCreate, PFN_WDFIOQUEUECREATE, HmWdfIoQueueCreate);
    SET(WdfIoQueueGetDevice, PFN_WDFIOQUEUEGETDEVICE, HmWdfIoQueueGetDevice);
    SET(WdfIoQueueRetrieveNextRequest, PFN_WDFIOQUEUERETRIEVENEXTREQUEST, HmWdfIoQueueRetrieveNextRequest);
    SET(WdfRequestForwardToIoQueue, PFN_WDFREQUESTFORWARDTOIOQUEUE, HmWdfRequestForwardToIoQueue);
    SET(WdfRequestRequeue, PFN_WDFREQUESTREQUEUE, HmWdfRequestRequeue);
    SET(WdfRequestRetrieveInputBuffer, PFN_WDFREQUESTRETRIEVEINPUTBUFFER, HmWdfRequestRetrieveInputBuffer);
    SET(WdfRequestRetrieveOutputBuffer, PFN_WDFREQUESTRETRIEVEOUTPUTBUFFER, HmWdfRequestRetrieveOutputBuffer);
