/* ------------------------------------------------------------------ */
/*  The framework's side: device add, removal, request dispatch        */
/* ------------------------------------------------------------------ */

HmDevice *DeviceAdd(int companion)
{
    static uint8_t driverObject[256];
    static UNICODE_STRING registryPath;
    NTSTATUS st = companion ? CompanionDriverEntry((PDRIVER_OBJECT)driverObject, &registryPath)
                            : DriverEntry((PDRIVER_OBJECT)driverObject, &registryPath);
    if (!NT_SUCCESS(st) || !g_deviceAdd) HmFail("DriverEntry failed 0x%08lx", (unsigned long)st);

    if (g_deviceCount >= (int)ARRAYSIZE(g_devices)) HmFail("too many devices in one stream");
    HmDevice *dev = (HmDevice *)WdfAlloc(sizeof(HmDevice), WK_DEVICE);
    dev->hwKey = g_nextHwKey ? g_nextHwKey : KeyNewDetached(L"hw");
    dev->hwSubKey = g_nextHwSubKey ? g_nextHwSubKey : KeyNewDetached(L"hw-sub");
    g_devices[g_deviceCount++] = dev;

    HmDeviceInit *init = (HmDeviceInit *)WdfAlloc(sizeof(HmDeviceInit), WK_INIT);
    DevnodeInstanceId(g_nextDevnodeProfile, g_nextDevnodeIndex, companion, init->instanceId, ARRAYSIZE(init->instanceId));
    init->hwKey = dev->hwKey;
    init->hwSubKey = dev->hwSubKey;
    g_addingDevice = dev;
    st = g_deviceAdd((WDFDRIVER)&g_driverKind, (PWDFDEVICE_INIT)init);
    g_addingDevice = NULL;
    RecOut("device.add", &st, 4);
    if (!NT_SUCCESS(st)) {
        /* The framework deletes a device whose add failed, which runs its
         * cleanup callback. */
        if (dev->context) DeviceRemove(dev);
        return NULL;
    }
    /* The threads it made start now, each running to its first wait. */
    for (int i = 0; i < dev->threadCount; i++) ThreadResume(dev->threads[i]);
    return dev;
}

/* The power-managed queues, or the others, purged as the framework purges
 * them for removal (FxIoStopProcessingForPowerPurgeManaged and
 * PurgeNonManaged, fxioqueue.cpp:5940-5971). */
static void PurgeQueues(HmDevice *dev, int powerManaged)
{
    for (int i = 0; i < dev->queueCount; i++)
        if (dev->queues[i]->powerManaged == powerManaged) {
            QueueCancelAll(dev->queues[i]);
            dev->queues[i]->purged = 1;
        }
}

/* The power down a stop and a surprise removal share: the self-managed
 * I/O suspend, then D0 exit to WdfPowerDeviceD3Final, then the release of
 * the hardware. The power-managed queues are held meanwhile with their
 * requests in them, which matters only to a request sent while stopped,
 * and no scenario sends one. */
static void PowerDownAndRelease(HmDevice *dev)
{
    WDFDEVICE h = (WDFDEVICE)dev;
    if (dev->smioStarted && dev->pnp.EvtDeviceSelfManagedIoSuspend)
        dev->pnp.EvtDeviceSelfManagedIoSuspend(h);
    if (dev->pnp.EvtDeviceD0ExitPreInterruptsDisabled)
        dev->pnp.EvtDeviceD0ExitPreInterruptsDisabled(h, WdfPowerDeviceD3Final);
    if (dev->pnp.EvtDeviceD0Exit) dev->pnp.EvtDeviceD0Exit(h, WdfPowerDeviceD3Final);
    if (dev->pnp.EvtDeviceReleaseHardware) dev->pnp.EvtDeviceReleaseHardware(h, NULL);
}

/* PnpCleanupForRemove (pnpstatemachine.cpp:2234-2264): the power-managed
 * queues purged, then the flush, which the self-managed I/O machine
 * takes from its Stopped state (selfmanagediostatemachine.cpp:55-60). */
static void CleanupForRemove(HmDevice *dev)
{
    PurgeQueues(dev, 1);
    if (dev->smioStarted && dev->pnp.EvtDeviceSelfManagedIoFlush)
        dev->pnp.EvtDeviceSelfManagedIoFlush((WDFDEVICE)dev);
}

void DeviceStart(HmDevice *dev)
{
    WDFDEVICE h = (WDFDEVICE)dev;
    if (dev->removed || dev->surprised || (dev->started && !dev->stopped)) HmFail("a start of a device that is not stopped");
    if (dev->pnp.EvtDevicePrepareHardware && !NT_SUCCESS(dev->pnp.EvtDevicePrepareHardware(h, NULL, NULL)))
        HmFail("EvtDevicePrepareHardware failed");
    if (dev->pnp.EvtDeviceD0Entry && !NT_SUCCESS(dev->pnp.EvtDeviceD0Entry(h, WdfPowerDeviceD3Final)))
        HmFail("EvtDeviceD0Entry failed");
    if (!dev->started && dev->pnp.EvtDeviceSelfManagedIoInit && !NT_SUCCESS(dev->pnp.EvtDeviceSelfManagedIoInit(h)))
        HmFail("EvtDeviceSelfManagedIoInit failed");
    if (dev->started && dev->pnp.EvtDeviceSelfManagedIoRestart && !NT_SUCCESS(dev->pnp.EvtDeviceSelfManagedIoRestart(h)))
        HmFail("EvtDeviceSelfManagedIoRestart failed");
    dev->started = 1;
    dev->stopped = 0;
    dev->smioStarted = 1;
}

void DeviceStop(HmDevice *dev)
{
    if (!dev->started || dev->stopped || dev->surprised || dev->removed) HmFail("a stop of a device that is not running");
    if (dev->pnp.EvtDeviceQueryStop && !NT_SUCCESS(dev->pnp.EvtDeviceQueryStop((WDFDEVICE)dev)))
        HmFail("EvtDeviceQueryStop refused the stop");
    g_releasingDevice = dev;
    PowerDownAndRelease(dev);
    g_releasingDevice = NULL;
    dev->stopped = 1;
}

void DeviceSurpriseRemove(HmDevice *dev)
{
    if (!dev->started || dev->surprised || dev->removed) HmFail("a surprise removal the harness does not model");
    g_releasingDevice = dev;
    if (dev->pnp.EvtDeviceSurpriseRemoval) dev->pnp.EvtDeviceSurpriseRemoval((WDFDEVICE)dev);
    if (!dev->stopped) PowerDownAndRelease(dev);
    CleanupForRemove(dev);
    g_releasingDevice = NULL;
    dev->surprised = 1;
}

void DeviceRemove(HmDevice *dev)
{
    if (dev->removed) return;
    g_releasingDevice = dev;
    if (dev->started && !dev->surprised) {
        if (!dev->stopped) PowerDownAndRelease(dev);
        CleanupForRemove(dev);
    }
    dev->removed = 1;
    /* A device never started has every queue purged here, as before the
     * lifecycle scenarios. */
    PurgeQueues(dev, 0);
    if (!dev->started) PurgeQueues(dev, 1);
    if (dev->smioStarted && dev->pnp.EvtDeviceSelfManagedIoCleanup)
        dev->pnp.EvtDeviceSelfManagedIoCleanup((WDFDEVICE)dev);
    if (dev->started)
        for (int i = 0; i < dev->timerCount; i++) dev->timers[i]->started = 0;
    if (dev->cleanup) dev->cleanup((WDFOBJECT)dev);
    g_releasingDevice = NULL;
    RecOut("device.removed", NULL, 0);
}

/* The three write-direction requests. MsHidUmdf hands each to the driver
 * with the report as the input buffer and the report id in
 * OutputBufferLength, with no output buffer the driver may read or write
 * (Windows-driver-samples hid/vhidmini2/driver/umdf2/util.c:98-129, "store
 * the report id in the OutputBufferLength field", and vhidmini.c:397-401,
 * 653, which takes IOCTL_HID_WRITE_REPORT the same way, review F2). */
static int IsWriteCode(ULONG code)
{
    return code == IOCTL_HID_WRITE_REPORT || code == IOCTL_UMDF_HID_SET_OUTPUT_REPORT
        || code == IOCTL_UMDF_HID_SET_FEATURE;
}

/* The output "buffer" a write request offers: a page the process may not
 * touch, so a driver that reads or writes it faults rather than reading a
 * value the HID class never put there. WdfRequestRetrieveOutputMemory and
 * WdfMemoryGetBuffer still hand it out, with the report id as its length,
 * which is how util.c:117-122 learns the id. */
static uint8_t *NoAccessPage(void)
{
    static uint8_t *page;
    if (!page) {
        page = (uint8_t *)VirtualAlloc(NULL, 4096, MEM_RESERVE | MEM_COMMIT, PAGE_NOACCESS);
        if (!page) HmFail("VirtualAlloc of the no-access page failed");
    }
    return page;
}

HmRequest *Ioctl(HmDevice *dev, const char *tag, ULONG code,
                 const void *in, size_t inLen, size_t outLen, const void *outInit, size_t outInitLen)
{
    if (IsWriteCode(code) && (outLen > 0xFF || outInit))
        HmFail("a write request carries its report id as OutputBufferLength and nothing else");
    HmRequest *r = (HmRequest *)calloc(1, sizeof(HmRequest));
    if (!r) HmFail("out of memory");
    r->kind = WK_REQUEST;
    r->nextAll = g_allRequests;
    g_allRequests = r;
    r->code = code;
    r->serial = ++g_serial;
    strncpy_s(r->tag, sizeof(r->tag), tag, _TRUNCATE);
    r->in = (uint8_t *)calloc(1, inLen ? inLen : 1);
    r->noAccess = IsWriteCode(code);
    r->out = r->noAccess ? NoAccessPage() : (uint8_t *)calloc(1, outLen ? outLen : 1);
    if (!r->in || !r->out) HmFail("out of memory");
    if (inLen) memcpy(r->in, in, inLen);
    r->inLen = inLen;
    r->outLen = outLen;
    if (outInit && outInitLen) memcpy(r->out, outInit, outInitLen < outLen ? outInitLen : outLen);
    HmQueue *q = dev->defaultQueue;
    if (!q || !q->ioctl) HmFail("the device has no default queue with a device-control callback");
    if (q->purged) {
        /* A purged queue accepts nothing: the framework completes the
         * request with STATUS_INVALID_DEVICE_STATE and the driver never
         * sees it (fxioqueue.cpp:2317-2335). Not recorded. */
        r->refused = 1;
        r->completed = 1;
        return r;
    }
    q->ioctl((WDFQUEUE)q, (WDFREQUEST)r, outLen, inLen, code);
    return r;
}

int QueueDepth(HmQueue *q) { return q ? q->count : 0; }

void WdfReset(void)
{
    while (g_allRequests) {
        HmRequest *n = g_allRequests->nextAll;
        free(g_allRequests->in);
        if (!g_allRequests->noAccess) free(g_allRequests->out);
        free(g_allRequests);
        g_allRequests = n;
    }
    for (int i = 0; i < g_deviceCount; i++) free(g_devices[i]->context);
    g_deviceCount = 0;
    while (g_allocs) { HmAlloc *n = g_allocs->next; free(g_allocs); g_allocs = n; }
    g_deviceAdd = NULL;
    g_addingDevice = NULL;
    g_nextHwKey = g_nextHwSubKey = NULL;
    g_serial = 0;
    IdentityReset();
}
